const html = items[0].json.html || '';
const inputs = [];

const regex = /<input\b([^>]+)>/gi;
let match;
while ((match = regex.exec(html)) !== null) {
  const attr = match[1];
  const type = /type="([^"]*)"/i.exec(attr)?.[1] || 'text';
  const name = /name="([^"]*)"/i.exec(attr)?.[1] || '';
  const autocomplete = /autocomplete="([^"]*)"/i.exec(attr)?.[1] || '';
  inputs.push({ type, name, autocomplete, raw: `<input ${attr}>` });
}

items[0].json.formInputs = inputs;
return items;

const input = $input.first();
const raw = input.json || {};
const binary = input.binary || {};

// 1) LLM-Content extrahieren
let content = raw;
if (raw.choices && raw.choices[0]?.message?.content) {
  content = raw.choices[0].message.content.trim();
}

// 2) JSON parsen
let analysis = {};
// URL ZWINGEND aus dem Input nehmen, nicht vom LLM raten lassen!
// Wir schauen, ob 'url' direkt im root json liegt
const safeUrl = raw.url || 'https://keine-url-gefunden.de'; 

if (typeof content === 'string') {
  const cleanContent = content.replace(/```json/g, '').replace(/```/g, '').trim();
  try {
    analysis = JSON.parse(cleanContent);
  } catch (e) {
    analysis = { 
        summary: "Fehler beim Parsen der KI-Antwort: " + cleanContent,
        has_captcha: null 
    };
  }
} else {
  analysis = content || {};
}

// 3) Daten normalisieren
const hasCaptcha = analysis.has_captcha;
const notApplicable = hasCaptcha === false;

const aa = analysis.aa_result || {};
const aaa = analysis.aaa_result || {};

let status = 'pass'; 
// Wenn Violation = true -> fail. Wenn undefined/null -> warning.
if (aa.is_violation === true || aaa.is_violation === true) {
    status = 'fail';
} else if (notApplicable) {
    status = 'not_applicable';
}

// Zusammenfassung bauen
let summaryText = analysis.summary || "Keine Zusammenfassung generiert.";

// Detailed Results Array
const detailedResults = [];

if (aa.is_violation === true) {
    detailedResults.push({
        issue_id: "3.3.8-accessible-authentication",
        description: aa.summary || "Barriere bei der Authentifizierung (AA) gefunden.",
        severity: aa.severity || "high",
        recommendation: "Alternative Authentifizierungsmethode anbieten (z.B. Magic Link, WebAuthn) oder Copy-Paste erlauben."
    });
}

// Markdown bauen (mit mehr Infos!)
const reportMarkdown = `## CSA Report für ${safeUrl}
**Status:** ${status.toUpperCase()}

**Zusammenfassung:**
${summaryText}

**Gefundene Formular-Elemente:**
${ (raw.formInputs || []).map(i => `- Type: ${i.type}, Name: ${i.name}`).join('\n') || "Keine Inputs erkannt." }
`;

// WICHTIG: Hier geben wir die "safeUrl" weiter, damit Build PDF sie hat
return [
  {
    json: {
      agent_name: 'CSA',
      wcag_criterion: '3.3.8 & 3.3.9',
      status: status,
      executive_summary: summaryText,
      detailed_results: detailedResults,

      url: safeUrl, // HIER IST DER FIX
      reportMarkdown: reportMarkdown,
      raw_analysis: analysis
    },
    binary: binary
  },
];

const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');

function sanitize(text) {
  if (!text) return '';
  let t = String(text);
  t = t.replace(/\u202F/g, ' ');
  t = t
    .split('')
    .map(ch => (ch.charCodeAt(0) > 255 ? ' ' : ch))
    .join('');
  return t;
}

// **foo**, __foo__, `code` rausziehen
function cleanInline(text) {
  if (!text) return '';
  return text
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1');
}

function yesNo(v) {
  if (v === true) return 'Ja';
  if (v === false) return 'Nein';
  return 'Unklar';
}

function violationColor(v) {
  if (v === true) return rgb(0.8, 0, 0);
  if (v === false) return rgb(0, 0.5, 0);
  return rgb(0.3, 0.3, 0.3);
}

function severityColor(sevRaw) {
  const sev = String(sevRaw || '').toLowerCase();
  if (sev === 'high' || sev === 'hoch') return rgb(0.8, 0, 0);
  if (sev === 'medium' || sev === 'mittel') return rgb(0.9, 0.5, 0);
  if (sev === 'low' || sev === 'niedrig') return rgb(0.7, 0.7, 0);
  return rgb(0.2, 0.2, 0.2);
}

async function run() {
  const item = items[0];
  const data = item.json || {};

  const url = data.url || 'unbekannte URL';
  const aa = data.details?.aa_result || {};
  const aaa = data.details?.aaa_result || {};
  const md = sanitize(data.reportMarkdown || '');

  const pdfDoc = await PDFDocument.create();
  let page = pdfDoc.addPage();
  let { width, height } = page.getSize();

  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  let y = height - 50;
  const marginX = 50;
  const maxWidth = width - 2 * marginX;

  function ensureSpace(lineHeight) {
    if (y - lineHeight < 50) {
      page = pdfDoc.addPage();
      ({ width, height } = page.getSize());
      y = height - 50;
    }
  }

  function wrapAndDraw(text, { size = 11, bold = false, lineGap = 4, color = rgb(0, 0, 0) } = {}) {
    text = sanitize(text);
    if (!text) return;

    const f = bold ? fontBold : fontRegular;
    const paragraphs = text.split('\n');

    for (const pRaw of paragraphs) {
      const p = pRaw.trim();
      if (!p) {
        y -= size;
        continue;
      }

      const words = p.split(' ');
      let line = '';

      for (const w of words) {
        const test = line ? line + ' ' + w : w;
        const tw = f.widthOfTextAtSize(test, size);

        if (tw > maxWidth && !line && w.length > 30) {
          let chunk = '';
          for (let i = 0; i < w.length; i++) {
            chunk += w[i];
            const cw = f.widthOfTextAtSize(chunk, size);
            if (cw > maxWidth) {
              ensureSpace(size + lineGap);
              page.drawText(chunk.slice(0, -1), { x: marginX, y, size, font: f, color });
              y -= size + lineGap;
              chunk = w[i];
            }
          }
          if (chunk) {
            ensureSpace(size + lineGap);
            page.drawText(chunk, { x: marginX, y, size, font: f, color });
            y -= size + lineGap;
          }
          continue;
        }

        if (tw > maxWidth && line) {
          ensureSpace(size + lineGap);
          page.drawText(line, { x: marginX, y, size, font: f, color });
          y -= size + lineGap;
          line = w;
        } else {
          line = test;
        }
      }

      if (line) {
        ensureSpace(size + lineGap);
        page.drawText(line, { x: marginX, y, size, font: f, color });
        y -= size + lineGap;
      }

      y -= 2;
    }
  }

  function drawList(label, arr) {
    if (!Array.isArray(arr) || !arr.length) return;
    wrapAndDraw(label + ':', { bold: true });
    arr.forEach(entry => wrapAndDraw('- ' + entry));
  }

  // Titel
  wrapAndDraw('CS-Agent Bericht – Accessible Authentication', {
    size: 18,
    bold: true,
    lineGap: 6,
  });
  y -= 4;

  // URL
  wrapAndDraw('URL:', { bold: true, size: 11 });
  wrapAndDraw(url, { size: 9 });
  y -= 6;

  // 3.3.8
  wrapAndDraw('3.3.8 Accessible Authentication (AA)', {
    size: 13,
    bold: true,
  });

  wrapAndDraw(`Verstoß: ${yesNo(aa.is_violation)}`, {
    color: violationColor(aa.is_violation),
  });

  if (aa.severity) {
    wrapAndDraw(`Schwere: ${aa.severity}`, {
      color: severityColor(aa.severity),
    });
  }

  if (aa.summary) {
    wrapAndDraw('Zusammenfassung:', { bold: true });
    wrapAndDraw(aa.summary);
  }

  drawList('Begründungen', aa.reasons);
  drawList('Evidenz', aa.evidence);

  y -= 8;

  // 3.3.9
  wrapAndDraw('3.3.9 Accessible Authentication (AAA)', {
    size: 13,
    bold: true,
  });

  wrapAndDraw(`Verstoß: ${yesNo(aaa.is_violation)}`, {
    color: violationColor(aaa.is_violation),
  });

  if (aaa.severity) {
    wrapAndDraw(`Schwere: ${aaa.severity}`, {
      color: severityColor(aaa.severity),
    });
  }

  if (aaa.summary) {
    wrapAndDraw('Zusammenfassung:', { bold: true });
    wrapAndDraw(aaa.summary);
  }

  drawList('Begründungen', aaa.reasons);
  drawList('Evidenz', aaa.evidence);

  // Markdown-Body aus reportMarkdown, mit Inline-Cleaner
  if (md) {
    y -= 12;
    wrapAndDraw('Detailanalyse', { bold: true, size: 13 });
    y -= 6;

    const lines = md.split(/\r?\n/);
    for (let rawLine of lines) {
      const lineTrim = rawLine.trimEnd();
      if (!lineTrim.trim()) {
        y -= 6;
        continue;
      }

      const headingMatch = lineTrim.match(/^(#{1,6})\s+(.*)$/);
      if (headingMatch) {
        const level = headingMatch[1].length;
        const text = cleanInline(headingMatch[2]);
        const size = level === 1 ? 14 : level === 2 ? 13 : 12;
        ensureSpace(size + 6);
        wrapAndDraw(text, { bold: true, size });
        continue;
      }

      const bulletMatch = lineTrim.match(/^\s*[-*]\s+(.*)$/);
      if (bulletMatch) {
        const text = cleanInline(bulletMatch[1]);
        ensureSpace(13);
        wrapAndDraw('- ' + text);
        continue;
      }

      ensureSpace(13);
      wrapAndDraw(cleanInline(lineTrim));
    }
  }

  // Screenshot (optional) wie gehabt
  const screenshot = item.binary?.screenshot;
  if (screenshot?.data) {
    const imgBuffer = Buffer.from(screenshot.data, 'base64');
    let image;
    try {
      image = await pdfDoc.embedPng(imgBuffer);
    } catch {
      image = await pdfDoc.embedJpg(imgBuffer);
    }

    const imgWidth = maxWidth;
    const imgHeight = image.height * (imgWidth / image.width);

    if (y - imgHeight < 60) {
      page = pdfDoc.addPage();
      ({ width, height } = page.getSize());
      y = height - 60;
    }

    page.drawImage(image, {
      x: marginX,
      y: y - imgHeight,
      width: imgWidth,
      height: imgHeight,
    });

    y -= imgHeight + 10;
  }

  const pdfBytes = await pdfDoc.save();
  const pdfBase64 = Buffer.from(pdfBytes).toString('base64');

  return [
    {
      json: data,
      binary: {
        report: {
          data: pdfBase64,
          mimeType: 'application/pdf',
          fileName: 'cs-agent-report.pdf',
        },
        ...(item.binary?.screenshot ? { screenshot: item.binary.screenshot } : {}),
      },
    },
  ];
}

return run();

const inputItem = $input.first().json;

return {
  json: {
    agent_name: inputItem.agent_name || "CSA",
    wcag_criterion: inputItem.wcag_criterion,
    status: inputItem.status,
    executive_summary: inputItem.executive_summary,
    detailed_results: inputItem.detailed_results,
  }
};

const src = items[0].json;

const screenshotBase64 = src.actionResults[0].data;

return [
  {
    json: {
      url: src.url,
      html: src.html,
      visibleText: src.actionResults.find(a => a.type === 'getText')?.data || ''
    },
    binary: {
      screenshot: {
        data: screenshotBase64,
        mimeType: 'image/png',
        fileName: 'auth-page.png'
      }
    }
  }
];
